def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker = next(v for row in grid for v in row if v != 8) if all(v == 8 or v == 7 for row in grid for v in row) else None
    # The non-background cells are the markers; fill gaps between consecutive markers.
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    marks = {v for row in grid for v in row if v != bg}
    if not marks:
        return out
    fill = 3
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] in marks]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                out[r][c] = fill
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] in marks]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                out[r][c] = fill
    return out
